{
  "items": [
    {
      "title": "German Longitudinal Election Study (GLES) – Federal Elections 2013 and 2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A major collection of German electoral datasets covering political attitudes, voting behavior, party preferences, campaign effects, and political participation. Includes surveys conducted around the 2013 and 2017 German federal elections. Particularly useful for studying electoral behavior, political polarization, and changes in voter preferences during the 2010s."
    },
    {
      "title": "GLES Rolling Cross-Section Surveys 2013 and 2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Provides survey data collected continuously during the 2013 and 2017 federal election campaigns. Tracks changes in voting intentions, political opinions, candidate evaluations, and responses to campaign events. Useful for examining how German political attitudes evolved during election campaigns."
    },
    {
      "title": "GLES Longitudinal Election Surveys – Cumulative Data 2009–2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "Combines election survey data across multiple German federal election cycles, including 2013 and 2017. Enables longitudinal comparisons of political preferences, voting behavior, and electoral trends during the 2010s."
    },
    {
      "title": "GLES Candidate Studies – German Federal Elections 2013 and 2017",
      "url_or_doi": "https://www.wzb.eu/de/forschung/beendete-forschungsprogramme/demokratie-und-demokratisierung/downloads",
      "justification": "Contains survey data from candidates representing major German political parties during the 2013 and 2017 federal elections. Covers political positions, candidate characteristics, and electoral competition. Useful for analyzing political representation, party ideology, and differences between candidates and voters."
    },
    {
      "title": "Manifesto Project Dataset – German Political Party Programs",
      "url_or_doi": "https://manifesto-project.wzb.eu/datasets/MPDS2020a",
      "justification": "Provides quantitative content analysis of political party election manifestos, including German parties during the 2010s. Covers ideological positions and policy priorities related to immigration, economic policy, welfare, European integration, and democracy. Particularly useful for examining ideological changes among CDU/CSU, SPD, FDP, Greens, Die Linke, and AfD."
    },
    {
      "title": "Manifesto Project – Political Party Manifesto Database",
      "url_or_doi": "https://gitlab.manifesto-project.wzb.eu/",
      "justification": "Provides access to political party manifestos and associated coding data for comparative political research. Includes German electoral programs from the 2010s. Useful for text analysis, measuring ideological polarization, and investigating changes in party positions during the rise of Alternative für Deutschland (AfD)."
    },
    {
      "title": "German Federal and State Election Results Since 1946 – Konrad Adenauer Foundation",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Offers historical election results for Germany, including federal, European, and state elections throughout the 2010s. Supports analysis of party vote shares, electoral participation, regional political differences, and shifts in support for established and emerging parties."
    },
    {
      "title": "German Bundestag Open Data – Parliamentary Records and Political Documents",
      "url_or_doi": "https://www.bundestag.de/services/opendata",
      "justification": "Official open-data portal of the German Bundestag providing parliamentary documents and structured information about legislative activity. Includes historical material relevant to the 2010s. Useful for investigating parliamentary debates, legislative priorities, government accountability, and political decision-making during Angela Merkel's chancellorship."
    },
    {
      "title": "GESIS Research Data Center Elections – German Political Surveys",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "Research data center providing access to German election studies and political opinion surveys, including Politbarometer, DeutschlandTREND, German state election studies, and GLES. These collections cover the 2010s and support research on political trust, public opinion, party identification, voting intentions, and electoral behavior."
    },
    {
      "title": "Comparative Study of Electoral Systems (CSES) – Integrated Module Dataset",
      "url_or_doi": "https://cses.org/data-download/cses-integrated-module-dataset-imd/",
      "justification": "International election survey dataset containing German electoral observations from the 2010s. Provides standardized variables on voting behavior, political institutions, democratic satisfaction, party preferences, and socioeconomic characteristics. Useful for comparing German political developments with those in other democracies."
    },
    {
      "title": "GLES European Candidate Study 2014",
      "url_or_doi": "https://www.gesis.org/gles/daten-und-dokumentation",
      "justification": "Includes data concerning candidates in the 2014 European Parliament elections, with German observations. Useful for analyzing the European dimension of German politics, candidate policy preferences, political representation, and attitudes toward European integration during the 2010s."
    },
    {
      "title": "GLES 2017 Federal Election – Candidate and Campaign Research Data",
      "url_or_doi": "https://www.wzb.eu/de/forschung/beendete-forschungsprogramme/demokratie-und-demokratisierung/downloads",
      "justification": "Provides access to election-related datasets covering candidates, campaign dynamics, and political behavior in the 2017 German federal election. Particularly relevant for researching the entry of AfD into the Bundestag, changes in party competition, and the political consequences of immigration debates."
    },
    {
      "title": "GLES 2013 Federal Election – Candidate Research Data",
      "url_or_doi": "https://www.wzb.eu/de/forschung/beendete-forschungsprogramme/demokratie-und-demokratisierung/downloads",
      "justification": "Contains candidate survey data associated with Germany's 2013 federal election. Supports analysis of political elites, candidate ideology, party competition, and political representation. Useful for studying German party politics following the eurozone crisis and during the early development of AfD."
    }
  ]
}
